// ============================================================================
// JSON Tokenization
// ============================================================================

class JsonTokenizer(pretty: Boolean = false) {
  import scala.util.parsing.json.JSONObject

  def tokenize(value: Any): Token = {
    val jsonStr = if (pretty) {
      scala.util.parsing.json.JSONObject(Map("value" -> value)).toString()
    } else {
      value.toString
    }
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Any, path: String): Option[Token] = {
    val parts = path.split("\.")
    var current: Any = value

    for (part <- parts) {
      current = current match {
        case map: Map[String, Any] if map.contains(part) => map(part)
        case list: List[Any] if part.forall(_.isDigit) =>
          val idx = part.toInt
          if (idx >= 0 && idx < list.length) list(idx) else return None
        case _ => return None
      }
    }

    Some(tokenize(current))
  }
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.filterNot(punctuation.contains)
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      None
    } else {
      val truncated = maxLength match {
        case Some(max) if processed.length > max => processed.take(max)
        case _ => processed
      }
      if (truncated.nonEmpty) Some(truncated) else None
    }
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")
    val tokens = mutable.ListBuffer.empty[Token]

    for ((word, i) <- words.zipWithIndex) {
      processToken(word) match {
        case Some(processed) =>
          val token = Token(
            value = processed,
            tokenType = TokenType.STRING,
            metadata = Map("position" -> i, "original" -> word)
          )
          tokens += token
        case None => ()
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    for (word <- text.split("\\s+")) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word) match {
        case Some(processed) => result += ((processed, start, end))
        case None => ()
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

class TokenizerBuilder[T] {
  private var normalizers: List[String => String] = List.empty
  private var validators: List[T => Boolean] = List.empty
  private var metadataMap: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators = validators :+ validator
    this
  }

  def withMetadata(metadata: (String, Any)*): TokenizerBuilder[T] = {
    metadataMap = metadataMap ++ metadata.toMap
    this
  }

  def build(): T => Token = { value: T =>
    // Validate
    validators.foreach { validator =>
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    normalizers.foreach { normalizer =>
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.STRING, metadataMap)
  }
}

